tool_info.command_line:
node --input-type=module - <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage();
await page.goto('http://127.0.0.1:5173/', {waitUntil:'domcontentloaded'});
await page.waitForTimeout(2500);
const data = await page.evaluate(() => {
  const ids = Array.from(document.querySelectorAll('[id]')).map(el => el.id);
  const semioIds = ids.filter(id => id.startsWith('semio.sketchpad')).sort();
  return {
    url: location.href,
    title: document.title,
    semioCount: semioIds.length,
    sample: semioIds.slice(0,120),
    hasToolbar: !!document.querySelector('#semio\\.sketchpad\\.toolbar'),
    hasNavbarLeft: !!document.querySelector('#semio\\.sketchpad\\.navbar\\.panelToggle\\.leftSidePanel'),
    hasNavbarRight: !!document.querySelector('#semio\\.sketchpad\\.navbar\\.panelToggle\\.rightSidePanel'),
    bodyText: document.body.innerText.slice(0,300)
  };
});
console.log(JSON.stringify(data,null,2));
await browser.close();
EOF

